:root{--ink:#17162b;--cream:#fffaf1;--pink:#e6a5ba;--violet:#7770a8}
*{box-sizing:border-box}body{margin:0;height:100dvh;overflow:hidden;font-family:Nunito,sans-serif;background:#17162b;color:white}.app{height:100%;position:relative;background:#c7c0de;isolation:isolate}.scene{position:absolute;inset:0;background:linear-gradient(160deg,rgba(34,29,68,.05),rgba(24,20,55,.42)),var(--scene);background-size:cover;background-position:center;transition:background 1s}.scene:after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 65% 45%,transparent 0 20%,rgba(14,12,38,.25) 100%)}
