.person{position:absolute;left:50%;bottom:0;width:310px;height:590px;transform:translateX(-50%)}.hair-back{position:absolute;width:285px;height:470px;left:12px;top:20px;border-radius:48% 48% 32% 32%;background:#332943;box-shadow:inset -24px -10px 0 #241e35}.hair-back:before,.hair-back:after{content:"";position:absolute;bottom:-20px;width:85px;height:300px;background:#332943;border-radius:60%}.hair-back:before{left:-16px;transform:rotate(8deg)}.hair-back:after{right:-16px;transform:rotate(-8deg)}
