.dialogue{position:absolute;z-index:10;left:3.5%;right:3.5%;bottom:max(20px,env(safe-area-inset-bottom));min-height:190px;padding:29px 44px 24px 44px;border:1px solid rgba(255,255,255,.55);border-radius:18px;background:linear-gradient(110deg,rgba(30,27,60,.94),rgba(55,49,88,.88));box-shadow:0 18px 60px rgba(13,11,36,.38);backdrop-filter:blur(14px)}.nameplate{position:absolute;top:-16px;left:28px;min-width:150px;text-align:center;padding:8px 18px;border-radius:30px;background:#e6a5ba;color:#2f294f;font:700 13px Nunito;letter-spacing:.12em;text-transform:uppercase}.text{max-width:920px;font:600 clamp(18px,2vw,25px) 'Cormorant Garamond',serif;line-height:1.35;min-height:85px}.continue{position:absolute;right:25px;bottom:18px;border:0;background:transparent;color:#f5bad0;font-size:24px;cursor:pointer;animation:pulse 1.2s infinite}@keyframes pulse{50%{transform:translateY(5px)}}
.choices{position:absolute;z-index:12;right:4%;bottom:230px;width:min(420px,92vw);display:flex;flex-direction:column;gap:10px}.choice{border:1px solid rgba(255,255,255,.5);border-radius:12px;padding:15px 18px;background:rgba(48,43,82,.92);color:white;text-align:left;font:700 15px Nunito;cursor:pointer;box-shadow:0 8px 25px rgba(12,10,35,.25)}.choice:hover{background:#e6a5ba;color:#30294e;transform:translateX(-4px)}
.menu{position:absolute;z-index:20;inset:0;display:grid;place-items:center;background:linear-gradient(135deg,rgba(28,25,61,.35),rgba(19,16,48,.85))}.menu.hidden{display:none}.menu-card{text-align:center;text-shadow:0 2px 20px rgba(17,13,45,.5)}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.35em}.title{font:700 clamp(52px,9vw,110px) 'Cormorant Garamond';line-height:.85;margin:20px 0}.subtitle{letter-spacing:.2em;text-transform:uppercase;font-size:11px;margin-bottom:35px}.main-btn{border:1px solid rgba(255,255,255,.75);border-radius:40px;padding:16px 38px;background:#f2c1d1;color:#30294f;font:700 15px Nunito;cursor:pointer;letter-spacing:.08em}.main-btn:hover{background:white}.savegrid{display:none}.menu-card.saved .savegrid{display:grid}.menu-card.saved .main-btn{display:none}.savegrid{grid-template-columns:repeat(3,150px);gap:12px}.slot{height:100px;border:1px solid rgba(255,255,255,.4);border-radius:12px;background:rgba(41,36,75,.75);color:white;cursor:pointer}.slot small{display:block;margin-top:8px}
@media(max-width:700px){.chapter{left:18px}.character{width:90vw;height:70%;left:58%}.person{transform:translateX(-50%) scale(.82);transform-origin:bottom}.dialogue{left:10px;right:10px;bottom:10px;min-height:200px;padding:27px 20px 22px}.text{font-size:18px;padding-right:15px}.moon{width:100px;height:100px}.choices{bottom:220px;right:10px}.savegrid{grid-template-columns:repeat(3,1fr);width:90vw}.topbar{right:10px}.chapter{top:76px}}
</style></head>
<body><main class="app"><div class="scene" id="scene"><div class="moon"></div><div class="stars" id="stars"></div></div><div class="chapter" id="chapter">Chapter 01 · The Winter Garden</div><div class="topbar"><button class="iconbtn" id="auto" title="Auto">A</button><button class="iconbtn" id="save" title="Save">▣</button><button class="iconbtn" id="menuBtn" title="Menu">≡</button></div><div class="character" id="character"><div class="person"><div class="hair-back"></div><div class="ear left"></div><div class="ear right"></div><div class="face"></div><div class="bangs"></div><div class="eye left"></div><div class="eye right"></div><div class="mouth"></div><div class="neck"></div><div class="dress"></div></div></div><div class="choices" id="choices"></div><div class="dialogue" id="dialogue"><div class="nameplate" id="name">Akari</div><div class="text" id="text"></div><button class="continue" id="continue">⌄</button></div><section class="menu" id="menu"><div class="menu-card" id="menuCard"><div class="eyebrow">A story by moonlight</div><h1 class="title">Moonlit<br>Atelier</h1><div class="subtitle">An evening in the winter garden</div><button class="main-btn" id="start">BEGIN STORY</button><div class="savegrid" id="savegrid"><button class="slot" data-slot="0">SLOT I<small>Empty</small></button><button class="slot" data-slot="1">SLOT II<small>Empty</small></button><button class="slot" data-slot="2">SLOT III<small>Empty</small></button></div></div></section></main>
<script>
const story=[
{c:'Akari',t:'The snow has gone quiet, hasn’t it? Even the fountain seems to be holding its breath.',scene:'moon',ch:'Chapter 01 · The Winter Garden'},
{c:'Akari',t:'I’m glad you came. I’ve been saving this little sketch for someone who notices details.'},
{c:'Akari',t:'Tell me… do you think a promise is still beautiful if it changes along the way?',choices:[{text:'Beauty can grow with change.',next:3,trust:1},{text:'A promise should stay unbroken.',next:5,trust:0},{text:'Let’s make a new promise together.',next:7,trust:2}]},
{c:'Akari',t:'I hoped you would say that. Then this evening can be a beginning, not a farewell.',next:8},
{c:'Narrator',t:'Akari smiles, warmth appearing where the moonlit cold had felt endless.'},
{c:'Akari',t:'That sounds stern. But I suppose I asked for honesty.',next:8},
{c:'Akari',t:'She studies the stars, then your face. “Both hands, one day at a time,” she says.'},
{c:'Akari',t:'You hold out your hand. Akari’s fingers meet yours with quiet certainty.',next:8},
{c:'Akari',t:'The lanterns wake across the garden. In their glow, every path seems possible.'},
{c:'Akari',t:'Which memory should we keep from tonight?',choices:[{text:'The warmth of your courage.',next:10},{text:'The sketch beneath the stars.',next:11},{text:'The promise we made together.',next:12}]},
{c:'Akari',t:'“Then I’ll carry that courage into tomorrow.” Akari lifts her lantern, and the garden blooms with warm light.',next:13},
{c:'Akari',t:'She carefully folds the sketch and places it beneath the lantern. “For the next winter,” she whispers.',next:13},
{c:'Akari',t:'Akari nods. “A promise we will both keep changing.” The stars seem to lean closer.',next:13},
{c:'Akari',t:'As the first bell rings, she looks at you without hesitation. “Until next moonlight.”'},
{c:'The End',t:'Moonlit Atelier · Thank you for sharing the evening',choices:[{text:'Read again',next:0},{text:'Save the ending',next:'save'}]}
];
let i=0,auto=false,trust=0,typing=false;const $=s=>document.querySelector(s);const stars=$('#stars');for(let n=0;n<48;n++){const s=document.createElement('i');s.style.left=Math.random()*100+'%';s.style.top=Math.random()*74+'%';s.style.opacity=.3+Math.random*.7;stars.appendChild(s)}
function show(n){if(n==='save'){$('#menu').classList.remove('hidden');$('#menuCard').classList.add('saved');return}i=n;const d=story[i];if(d.ch)$('#chapter').textContent=d.ch;if(d.scene)setScene();$('#name').textContent=d.c;$('#choices').innerHTML='';type(d.t);if(d.choices)showChoices(d.choices)}
function type(t){typing=true;let k=0;$('#text').textContent='';clearInterval(window.typeTimer);window.typeTimer=setInterval(()=>{$('#text').textContent=t.slice(0,k++);if(k>t.length){clearInterval(window.typeTimer);typing=false;if(auto&&!story[i].choices)setTimeout(()=>advance(),1300)}},18)}
function advance(){const d=story[i];if(typing){clearInterval(window.typeTimer);$('#text').textContent=d.t;typing=false;return}if(d.choices)return;if(d.next!==undefined)show(d.next);else show(i+1)}
function showChoices(cs){setTimeout(()=>{cs.forEach(c=>{const b=document.createElement('button');b.className='choice';b.textContent=c.text;b.onclick=()=>{trust+=c.trust||0;show(c.next)};$('#choices').appendChild(b)})},typing?350:0)}
function setScene(){document.body.style.setProperty('--scene','linear-gradient(180deg,#8b95bd 0%,#c5bdd3 55%,#585273 56%,#29264a 100%)')}
$('#continue').onclick=advance;$('#dialogue').onclick=e=>{if(e.target===e.currentTarget||e.target.classList.contains('text'))advance()};$('#start').onclick=()=>{$('#menu').classList.add('hidden');show(0)};$('#menuBtn').onclick=()=>{$('#menu').classList.remove('hidden');$('#menuCard').classList.remove('saved')};$('#auto').onclick=e=>{auto=!auto;e.style.background=auto?'#e6a5ba':'rgba(35,31,70,.35)';if(auto&&!typing&&!story[i].choices)setTimeout(advance,1300)};$('#save').onclick=()=>{$('#menu').classList.remove('hidden');$('#menuCard').classList.add('saved')};
document.querySelectorAll('.slot').forEach(s=>{const n=+s.dataset.slot;const saved=JSON.parse(localStorage.getItem('moon-slot-'+n)||'null');if(saved){s.querySelector('small').textContent='Saved · '+saved.chapter} s.onclick=()=>{if(s.querySet)return;if(saved&&Date.now()<1e15){show(saved.index);trust=saved.trust||0}else{localStorage.setItem('moon-slot-'+n,JSON.stringify({index:i,trust,chapter:$('#chapter').textContent.replace('Chapter 0','Ch. ')}));s.querySelector('small').textContent='Saved · just now'}}});
document.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter')advance();if(e.key==='Escape')$('#menuBtn').click()});setScene();
</script></body></html>
